CalendarEvent _event(Recurrence r, DateTime start) =>
    CalendarEvent(sourceId: 's', calendarId: 'c', title: 'T', start: start,
        end: start.add(const Duration(hours: 1)), recurrence: r);

List<String> _days(Iterable<DateTime> xs) => [for (final x in xs) isoDate(x)];

void main() {
  test('Serien wie Google (RFC 5545) – erste Vorkommen und ein späteres Fenster', () {
    for (final (rule, start, first, window) in _cases) {
      final r = parseRule(rule, start);
      expect(r, isNotNull, reason: rule);
      final e = _event(r!, start);
      final all = occurrenceStarts(e, dateOnly(start), DateTime(start.year + 40)).take(12);
      expect(_days(all), first, reason: rule);
      expect(_days(occurrenceStarts(e, DateTime(2031), DateTime(2031, 7))), window, reason: '$rule (2031)');
      // Uhrzeit bleibt
      expect(all.first.hour, start.hour, reason: rule);
      // Über JSON (so liegt es im Repo) gleich
      final back = CalendarEvent.fromJson(e.toJson(), 's');
      expect(_days(occurrenceStarts(back, dateOnly(start), DateTime(start.year + 40)).take(12)), first,
          reason: '$rule (JSON)');
      // Hin und zurück zum Kalenderspeicher: gleiche kanonische Form
      final again = parseRule(providerRule(r, start, false), start);
      expect(canonicalRule(again!, start), canonicalRule(r, start), reason: rule);
    }
  });

  test('Einfache Regeln bleiben im alten Format, alles andere als RRULE', () {
    final s = DateTime(2026, 11, 10, 20); // 2. Dienstag
    expect(parseRule('FREQ=MONTHLY;BYMONTHDAY=10', s)!.toJson(), {'freq': 'monthly', 'interval': 1});
    expect(parseRule('FREQ=WEEKLY;WKST=SU;BYDAY=TU', s)!.toJson(), {'freq': 'weekly', 'interval': 1});
    expect(parseRule('FREQ=YEARLY;BYMONTH=11;BYMONTHDAY=10', s)!.toJson(), {'freq': 'yearly', 'interval': 1});
    final j = parseRule('FREQ=MONTHLY;BYDAY=2TU;COUNT=5', s)!.toJson();
    expect(j, {'freq': 'rrule', 'rrule': 'FREQ=MONTHLY;BYDAY=2TU', 'count': 5});
    // Ältere App-Versionen kennen „rrule“ nicht und zeigen den Termin einmal an
    expect(RecurrenceFreq.tryCode(j['freq'] as String), isNull);
    // Teile, die diese Version nicht kennt: lieber einmal anzeigen als falsch wiederholen
    expect(Recurrence.tryFromJson({'freq': 'rrule', 'rrule': 'FREQ=YEARLY;BYWEEKNO=20'}), isNull);
    expect(parseRule('FREQ=HOURLY;INTERVAL=4', s), isNull);
    expect(parseRule('FREQ=DAILY;INTERVAL=2;BYDAY=MO', s), isNull);
  });

  test('Texte', () {
    String t(String rule, DateTime s) => recurrenceText(parseRule(rule, s)!, s);
    expect(t('FREQ=MONTHLY;BYDAY=2TU', DateTime(2026, 11, 10)), 'Monatlich am 2. Dienstag');
    expect(t('FREQ=MONTHLY;INTERVAL=2;BYDAY=-1FR', DateTime(2026, 11, 27)), 'Alle 2 Monate am letzten Freitag');
    expect(t('FREQ=MONTHLY;BYMONTHDAY=1,15', DateTime(2026, 11, 1)), 'Monatlich am 1. und 15.');
    expect(t('FREQ=MONTHLY;BYMONTHDAY=-1', DateTime(2026, 11, 30)), 'Monatlich am letzten Tag');
    expect(t('FREQ=MONTHLY;BYDAY=MO,TU,WE,TH,FR;BYSETPOS=-1', DateTime(2026, 11, 30)),
        'Monatlich am letzten Werktag');
    expect(t('FREQ=YEARLY;BYMONTH=5;BYDAY=2SU', DateTime(2027, 5, 9)), 'Jährlich am 2. Sonntag im Mai');
    expect(t('FREQ=MONTHLY;BYDAY=2TU;COUNT=4', DateTime(2026, 11, 10)), 'Monatlich am 2. Dienstag, 4×');
    expect(t('FREQ=MONTHLY;BYMONTHDAY=12', DateTime(2026, 11, 12)), 'Monatlich am 12.');
  });

  test('Serie bis hier beenden behält die Regel', () {
    final r = parseRule('FREQ=MONTHLY;BYDAY=2TU', DateTime(2026, 11, 10))!;
    final cut = r.copyWith(until: DateTime(2027, 1, 31), clearCount: true);
    expect(cut.byDay, [const NthWeekday(2, 2)]);
    final e = _event(cut, DateTime(2026, 11, 10, 20));
    expect(_days(occurrenceStarts(e, DateTime(2026, 11), DateTime(2028))), ['2026-11-10', '2026-12-08', '2027-01-12']);
  });
}
